#da-console .da-form-actions a{font-size:12px}#da-console .da-delete{height:36px;background:white;border:1px solid #e4b9bc;color:#ac343c;border-radius:5px;padding:8px 14px;font-weight:600}
#da-console .da-alias-back{margin:0 0 16px;font-size:13px}#da-console .da-alias-toolbar{margin:0 0 14px;font-size:12px}
#da-console .da-alias-empty{display:block;color:var(--da-muted);font-size:10px;max-width:190px;margin-top:4px}
