#da-console .da-alias-preview{position:relative;display:inline-block}
#da-console .da-alias-tooltip{display:none;position:absolute;top:100%;left:0;z-index:20;min-width:240px;width:max-content;max-width:min(320px,65vw);padding:12px 14px;background:#20334e;color:#fff;border-radius:7px;box-shadow:0 5px 18px #172a4a33;font-size:12px;font-weight:400;overflow-wrap:anywhere}
