#da-console .da-alias-preview:hover>.da-alias-tooltip,#da-console .da-alias-preview:focus-within>.da-alias-tooltip{display:block}
#da-console{--da-blue:#315cd5;--da-ink:#1c2b42;--da-muted:#64748b;--da-line:#e3e9f1;--da-bg:#f5f7fb;color:var(--da-ink);font:14px/1.5 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;background:var(--da-bg);border:1px solid var(--da-line);border-radius:12px;margin:8px 0 24px;overflow:hidden}
