s{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin-bottom:18px}#da-console .da-card{border:1px solid var(--da-line);border-radius:9px;padding:18px;background:white;color:var(--da-ink);display:flex;flex-direction:column;min-width:0}#da-console .da-card:hover{box-shadow:0 3px 14px #172a4a0d;text-decoration:none;border-color:#b9caed}#da-console .da-card>span{font-size:12px;color:#52617a;font-weight:600}#da-console .da-card strong{font-size:30px;line-height:1.4;letter-spacing:-.8px;font-variant-numeric:tabular-nums;margin:8px 0}#da-console .da-card small{font-size:10px;color:var(--da-muted)}#da-console .da-card small span{float:right}#da-console .da-card-dns strong{color:var(--da-blue)}#da-console .da-card-pass strong{color:#168367}#da-console .da-card-block strong{color:#c34d55}#da-console .da-panel{border:1px solid var(--da-line);border-radius:9px;background:white;padding:20px;margin-bottom:18px;min-width:0}#da-console .da-panel-title{display:flex;justify-content:space-between;align-items:start;gap:12px;margin-bottom:18px}#da-console .da-panel-title p{font-size:11px;color:var(--da-muted);margin-top:4px}#da-console .da-panel-title>a,#da-console .da-panel-title>span{font-size:11px;flex-shrink:0}#da-console .da-two{display:grid;grid-template-columns:1fr 1fr;gap:18px}#da-console .da-charts{display:grid;grid-template-columns:1fr 1fr;gap:24px}#da-console .da-chart{width:100%;height:auto;margin-top:12px;overflow:visible}#da-console .da-axis{fill:#78869c;font-size:15px}#da-console .da-grid{stroke:#e3e9f1;stroke-width:1}#da-console .da-bar-dns{fill:#6384e8}#da-console .da-bar-pass{fill:#59b69e}#da-console .da-bar-block{fill:#df7c83}#da-console .da-bar-missing{fill:#d7dee9}#da-console .da-dot{display:inline-block;width:7px;height:7px;border-radius:50%;margin:0 4px 1px 0}#da-console .da-dot.da-dns{background:#6384e8}#da-console .da-dot.da-pass{background:#59b69e}#da-console .da-dot.da-block{background:#df7c83;margin-left:12px}#da-console .da-charts small{font-size:10px;font-weight:400;color:var(--da-muted);margin-left:5px}#da-console .da-footnote{font-size:11px;color:var(--da-muted);margin-top:14px;line-height:1.6}#da-console .da-rank{position:relative;display:grid;grid-template-columns:minmax(0,1fr) auto;gap:12px;padding:11px 0 15px;margin-bottom:3px;color:var(--da-ink);font-size:12px}#da-console .da-rank>span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}#da-console .da-rank strong{font-size:12px;font-variant-numeric:tabular-nums}#da-console .da-rank i{position:absolute;bottom:4px;left:0;background:#dce6fd;height:3px;border-radius:2px;max-width:100%}#da-console .da-table-wrap{width:100%;overflow:auto}#da-console .da-table{width:100%;border-collapse:collapse;font-size:12px;margin:0}#da-console .da-table th{background:#f7f9fc;color:#62718a;border-bottom:1px solid var(--da-line);white-space:nowrap;font-weight:500;text-align:left;padding:10px}#da-console .da-sort{border:0;background:none;color:inherit;font-size:10px;letter-spacing:.25px;padding:0;text-align:inherit}#da-console .da-sort span{color:#a4b0c4}#da-console .da-table td{padding:11px 10px;border-bottom:1px solid #edf1f6;max-width:300px;overflow-wrap:anywhere;vertical-align:middle;font-variant-numeric:tabular-nums}#da-console .da-table tr:last-child td{border:0}#da-console .da-table tbody tr:hover{background:#fafcff}#da-console .da-table time{font-size:11px;white-space:nowrap;color:var(--da-muted)}#da-console .da-detail{font-size:11px;border:0;background:none;color:var(--da-blue);padding:0;white-space:nowrap}#da-console .da-empty{padding:28px 12px!important;text-align:center;color:var(--da-muted);font-size:12px}#da-console .da-table-tools{display:flex;justify-content:space-between;align-items:end;gap:12px;margin:0 0 16px}#da-console .da-table-tools span{font-size:10px;color:var(--da-muted)}#da-console .da-table-tools input{width:260px}#da-console .da-search-empty{font-size:12px;color:var(--da-muted);padding:15px}#da-console .da-coverage-grid{display:grid;grid-template-columns:1fr 1fr;gap:24px;margin-bottom:24px}#da-console .da-coverage-grid h3{margin-bottom:8px}#da-console .da-coverage-grid p,#da-console .da-panel>p{font-size:12px;color:var(--da-muted)}#da-console .da-coming{padding:60px 30px;text-align:center}#da-console .da-coming p{max-width:550px;margin:14px auto}#da-console .da-symbol{font-size:46px;color:#8b9fca;margin-bottom:16px}#da-console .da-coming .da-pill{margin-top:14px}#da-console .da-notice{padding:12px 24px;background:#eef3fd;font-size:12px}#da-console .da-danger{background:#fff0ed;color:#9b3434}#da-console [hidden]{display:none!important}#da-console.da-js .da-view:not(.da-visible){display:none}#da-console dialog{color:var(--da-ink);border:1px solid var(--da-line);border-radius:12px;max-width:min(630px,90vw);width:630px;padding:28px;box-shadow:0 20px 70px #13223d44}#da-console dialog::backdrop{background:#13223d66}#da-console .da-dialog-header{display:flex;justify-content:space-between;gap:20px}#da-console .da-dialog-header button{border:0;background:#f0f3f8;border-radius:50%;width:32px;height:32px}#da-console dl{display:grid;grid-template-columns:150px minmax(0,1fr);gap:12px 20px;font-size:12px;margin:24px 0}#da-console dt{font-weight:500;color:var(--da-muted)}#da-console dd{margin:0;overflow-wrap:anywhere}
@media(min-width:1500px){#da-console .da-main{padding:26px 32px}#da-console .da-cards{gap:20px}#da-console .da-card{padding:22px}}
@media(max-width:1000px){#da-console .da-shell{grid-template-columns:140px minmax(0,1fr)}#da-console .da-main{padding:18px}#da-console .da-nav{padding:22px 6px}#da-console .da-nav>a{font-size:12px;padding:10px 8px;gap:7px}#da-console .da-cards{grid-template-columns:repeat(2,minmax(0,1fr))}#da-console .da-header{padding:20px}#da-console h1 span{display:block;margin:2px 0 0}#da-console .da-charts{grid-template-columns:1fr}#da-console .da-two{grid-template-columns:1fr}#da-console .da-chart{max-height:160px}}
@media(max-width:620px){#da-console .da-header{align-items:start;flex-direction:column;padding:18px}#da-console .da-shell{display:block}#da-console .da-nav{display:flex;flex-wrap:wrap;border-right:0;border-bottom:1px solid var(--da-line);padding:8px;gap:2px}#da-console .da-nav>a{padding:7px 9px;margin:0;gap:5px}#da-console .da-nav-label,#da-console .da-nav-footer,#da-console .da-nav-icon,#da-console .da-nav-count{display:none}#da-console .da-main{padding:12px}#da-console .da-filters{padding:12px;gap:10px}#da-console .da-filters>label{flex:1 1 130px}#da-console .da-filters input{width:100%}#da-console .da-card{padding:14px}#da-console .da-card strong{font-size:25px}#da-console .da-card small{font-size:9px}#da-console .da-panel{padding:14px}#da-console .da-panel-title{flex-wrap:wrap}#da-console .da-table-tools{align-items:start;flex-direction:column}#da-console .da-coverage-grid{grid-template-columns:1fr}#da-console .da-context>div{gap:8px;flex-wrap:wrap}#da-console .da-advanced>div{display:grid}#da-console .da-coming{padding:35px 18px}#da-console dl{grid-template-columns:1fr;gap:5px}#da-console dd{margin-bottom:12px}}
@media(prefers-reduced-motion:no-preference){#da-console .da-card{transition:border-color .15s,box-shadow .15s}}
#da-console .da-client-cards{grid-template-columns:repeat(3,minmax(0,1fr));margin-top:12px}#da-console .da-feed-filters{display:flex;align-items:center;gap:8px;flex-wrap:wrap}#da-console .da-feed-link{padding:6px 12px;border:1px solid var(--da-line);border-radius:6px;font-size:12px;background:white}#da-console .da-feed-link[aria-current]{background:#e8eefc;border-color:#b7c8f4;font-weight:600}#da-console .da-feed-filters>span{font-size:11px;margin-left:auto}#da-console .da-pagination{display:flex;justify-content:space-between;align-items:center;margin-top:18px;font-size:12px}#da-console .da-review{border:1px solid #d8e0ec;border-radius:5px;background:#fafcff;color:var(--da-blue);padding:4px 7px;font-size:10px;margin:2px;white-space:nowrap}#da-console .da-policy-buttons{display:flex;gap:12px;margin-top:20px}#da-console button:disabled{cursor:not-allowed;opacity:.55}#da-console .da-policy-buttons>button{border-radius:5px;padding:8px 12px}#da-console .da-table td:last-child:has(.da-review){min-width:110px}
@media(max-width:620px){#da-console .da-client-cards{gap:7px}#da-console .da-client-cards .da-card{padding:10px}#da-console .da-client-cards .da-card strong{font-size:24px}#da-console .da-client-cards .da-card small{display:none}#da-console .da-client-cards .da-card>span{font-size:10px}#da-console .da-feed-filters>span{width:100%;margin:5px 0}}
/* Keep the client's decisions and review controls together in narrow panels,
   including pfSense's native theme/sidebar. No horizontal hunt for actions. */
#da-client{container-type:inline-size}
#da-console .da-sort span::after{content:' ↕'}
#da-console th[aria-sort="ascending"] .da-sort span::after{content:' ↑';color:var(--da-blue)}
#da-console th[aria-sort="descending"] .da-sort span::after{content:' ↓';color:var(--da-blue)}
#da-console .da-card-sort{display:none}
#da-console .da-client-timeline td:nth-child(5){white-space:nowrap}
@container (max-width:900px){
 #da-console.da-js .da-card-sort{display:flex;align-items:center;flex-wrap:wrap;gap:8px;margin:0 0 10px}
 #da-console .da-card-sort select,#da-console .da-card-sort button{min-height:32px;padding:4px 8px;border:1px solid var(--da-line);border-radius:5px;background:#fff;color:inherit}
 #da-console .da-client-timeline{display:block;width:100%}
 #da-console.da-js .da-client-timeline .da-sort{display:none}
 #da-console .da-client-timeline thead{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
 #da-console .da-client-timeline tbody{display:block}
 #da-console .da-client-timeline tr[data-row]{display:grid;contain:layout style;grid-template-columns:minmax(0,3fr) minmax(0,2fr);grid-template-areas:"stamp result" "target target" "protocol rule" "evidence evidence" "tags tags" "actions actions";gap:10px 14px;border:1px solid var(--da-line);border-radius:8px;padding:14px;min-width:0}
 #da-console .da-client-timeline tr[data-row]:not(:last-child){margin-bottom:12px}
 #da-console .da-client-timeline tr[data-row] td{border:0!important;max-width:none;min-width:0;padding:0;overflow-wrap:anywhere}
 #da-console .da-client-timeline td:nth-child(1){grid-area:stamp}
 #da-console .da-client-timeline td:nth-child(2){grid-area:result;justify-self:end}
 #da-console .da-client-timeline td:nth-child(3){grid-area:target;font-size:14px;font-weight:600}
 #da-console .da-client-timeline td:nth-child(4){grid-area:protocol}
 #da-console .da-client-timeline td:nth-child(5){grid-area:rule;text-align:right;white-space:normal}
 #da-console .da-client-timeline td:nth-child(6){grid-area:evidence}
 #da-console .da-client-timeline td:nth-child(7){grid-area:tags}
 #da-console .da-client-timeline td:nth-child(8){grid-area:actions;display:flex;flex-wrap:wrap;gap:8px;padding-top:10px;border-top:1px solid var(--da-line)!important}
 #da-console .da-client-timeline td:nth-child(3)::before,#da-console .da-client-timeline td:nth-child(4)::before,#da-console .da-client-timeline td:nth-child(5)::before{content:attr(data-label);display:block;font-size:10px;font-weight:400;color:var(--da-muted);margin-bottom:3px}
 #da-console .da-client-timeline .da-review{margin:0;min-height:32px}
 #da-console .da-client-timeline .da-empty{display:block}
}
#da-console .da-investigate{display:flex;flex-wrap:wrap;gap:10px;margin:14px 0}
#da-console .da-inspect{container-type:inline-size}
#da-console .da-inspect[data-panel="domain"] .da-client-cards{grid-template-columns:repeat(4,minmax(0,1fr))}
@container (max-width:900px){#da-console .da-inspect[data-panel="domain"] .da-client-cards{grid-template-columns:repeat(2,minmax(0,1fr))}}
/* Compact inspection rows retain every column on phones, with horizontal
   scrolling instead of converting each observation into a tall tile. */
#da-console .da-inspect-table{min-width:600px}
#da-console .da-inspect-table td{padding:7px 9px;line-height:1.35}
#da-console .da-inspect-table .da-pill{white-space:normal}
#da-console .da-recent-mappings .da-table-wrap{max-height:360px;overflow:auto}
#da-console .da-recent-mappings th{position:sticky;top:0;z-index:1}


#da-console .da-destination{display:grid;gap:3px;min-width:0}
#da-console .da-destination-name{font-weight:600}
#da-console .da-destination-ip{font-size:11px;font-weight:400}
#da-console .da-destination>small{font-size:10px;font-weight:400}
#da-console .da-destination-history{font-size:10px;font-weight:400;color:var(--da-muted)}
#da-console .da-destination-history summary{cursor:pointer;width:fit-content}
#da-console .da-destination-history>div{border-left:2px solid var(--da-line);padding:4px 0 4px 9px;margin-top:5px}
#da-console .da-destination-history p{margin:4px 0 8px}
#da-console .da-destination-history small{font-size:10px}
